+    }
+    function statMarkup(label, value, icon, id) { return `<div class="stat"><div class="stat-top"><span>${label}</span><span>${icon}</span></div><div class="stat-value">${value}%</div><div class="meter"><i id="meter-${id}" style="width:${value}%"></i></div></div>`; }
+    function renderGame() {
+      if (!game) return;
+      $('#familyName').textContent = `${game.name}’s family`;
+      $('#familyMeta').textContent = `${locations[game.home]} · Day ${Math.min(game.day + 1, 5)} of 5`;
