+      $('#statsStrip').innerHTML = statMarkup('Family bond',game.bond,'♡','bond') + statMarkup('Patience',game.patience,'✿','patience') + statMarkup('Your energy',game.energy,'☼','energy') + statMarkup('Joy',game.joy,'✦','joy');
+      $('#siblingSideCount').textContent = `${game.siblings.length} ${game.siblings.length === 1 ? 'sibling' : 'siblings'}`;
+      $('#gameSiblings').innerHTML = game.siblings.map((s,i) => `<div class="sibling-mini"><div class="mini-face">${sceneFace(s,i)}</div><div class="mini-info"><strong>${escapeHtml(s.name)}</strong><small>${s.age} years old · ${s.gender === 'Prefer not to say' ? 'your sibling' : s.gender.toLowerCase()}</small></div><span class="mood" title="${s.bond > 60 ? 'Feeling connected' : 'Having a day'}">${moodFor(s.bond)}</span></div>`).join('');
+      $('#questCount').textContent = `${game.day} / 5`;
+      $('#questMeter').style.width = `${game.day / 5 * 100}%`;
+      $('#journal').innerHTML = game.entries.length ? game.entries.slice().reverse().map((entry) => `<div class="journal-entry"><strong>${entry.title}</strong><br>${entry.text}</div>`).join('') : '<div class="journal-entry">Your story starts with the little things. Your choices will show up here.</div>';
+      if (!game.pending) renderEvent();
+    }
+
+    function renderEvent() {
+      const event = events[Math.min(game.day, events.length - 1)];
+      const sibling = game.siblings[game.day % game.siblings.length];
+      const sibling2 = game.siblings.length > 1 ? game.siblings[(game.day + 1) % game.siblings.length] : sibling;
+      $('#dayLabel').textContent = `Day ${game.day + 1} · ${event.label}`;
+      $('#storyTitle').textContent = event.title;
+      $('#storyText').textContent = event.text(game.siblings);
+      $('#sceneEvent').textContent = ['A new day together','A little disagreement','Rainy day at home','A quiet conversation','Weekend together'][game.day];
+      $('#scenePlayer').textContent = sceneFace({gender:game.gender, age:game.age}, 1);
+      $('#sceneSibling').textContent = sceneFace(sibling, game.day);
+      $('#sceneSibling2').style.display = game.siblings.length > 1 ? '' : 'none';
+      $('#sceneSibling2').textContent = sceneFace(sibling2, game.day + 1);
+      $('#choices').innerHTML = event.choices.map((choice, i) => `<button class="choice" data-choice="${i}"><strong>${choice.title}</strong><small>${choice.note}</small></button>`).join('');
+      $('#choices').querySelectorAll('button').forEach((button) => button.addEventListener('click', () => makeChoice(Number(button.dataset.choice))));
+      $('#questText').textContent = game.day === 0 ? 'Try a little kindness, a little listening, and remember to look after yourself too.' : 'There is no perfect answer. Notice what helps your family feel safe—and what helps you, too.';
+    }
+
+    function makeChoice(choiceIndex) {
+      if (game.pending || game.done) return;
+      const event = events[game.day];
+      const choice = event.choices[choiceIndex];
+      const sibling = game.siblings[game.day % game.siblings.length];
+      for (const key of ['bond','patience','energy','joy']) game[key] = bounded(game[key] + choice.effect[key]);
+      sibling.bond = bounded(sibling.bond + choice.effect.bond * 1.2);
+      sibling.mood = bounded(sibling.mood + choice.effect.joy);
+      game.pending = true;
+      const result = choice.result(game.siblings);
+      game.entries.push({ title:`Day ${game.day + 1} · ${event.title}`, text:result });
+      renderGame();
+      $('#storyText').textContent = result;
+      $('#choice-label');
+      $('#choices').innerHTML = `<div style="grid-column:1/-1;background:#edf2e8;border:1px solid #e3ebdc;padding:15px 16px;border-radius:14px;color:#516951;font-size:12px;line-height:1.55"><strong style="display:block;margin-bottom:4px">A moment to remember</strong>${escapeHtml(result)}<div style="margin-top:8px;color:#879587;font-size:10px">Family bond ${formatChange(choice.effect.bond)} · Patience ${formatChange(choice.effect.patience)} · Energy ${formatChange(choice.effect.energy)} · Joy ${formatChange(choice.effect.joy)}</div></div><button class="primary" id="nextDay" style="grid-column:1/-1;justify-self:end">${game.day === 4 ? 'See how your week went' : 'Continue to tomorrow'} <span aria-hidden="true">→</span></button>`;
+      $('#choices').querySelector('#nextDay').addEventListener('click', advanceDay);
+      $('#dayLabel').textContent = `Day ${game.day + 1} · ${event.label} · You showed up`;
+      $('#questText').textContent = ['You took a first step. There are lots of ways to care—and asking, listening, and setting limits all count.','You practiced making room for everyone. A fair solution can take patience.','You let a feeling exist without having to fix it instantly. That is a kind of care.','You offered support without needing to have every answer.','You made room for your siblings and for yourself. That balance is worth practicing.'][game.day];
+    }
+    function formatChange(value) { return `${value > 0 ? '+' : ''}${value}`; }
+    function advanceDay() {
+      game.pending = false;
+      game.day++;
+      if (game.day >= 5) { game.done = true; showEnding(); return; }
+      renderGame();
+      window.scrollTo({top:0,behavior:'smooth'});
+    }
+
 </body>
 </html>

input.oldString:
function advanceDay() {
  game.pending = false;
  game.day++;
  if (game.day >= 5) { game.done = true; showEnding(); return; }
  renderGame();
  window.scrollTo({top:0,behavior:'smooth'});
}

input.newString:
  function advanceDay() {
    game.pending = false;
    game.day++;
    if (game.day >= 5) { game.done = true; showEnding(); return; }
    renderGame();
    window.scrollTo({top:0,behavior:'smooth'});
  }

  function openModal(html) {
    $('#modal').innerHTML = html;
    $('#modalBackdrop').classList.add('open');
    $('#modal').querySelectorAll('[data-close]').forEach((button) => button.addEventListener('click', closeModal));
  }
  function closeModal() { $('#modalBackdrop').classList.remove('open'); }
  $('#modalBackdrop').addEventListener('click', (event) => { if (event.target === $('#modalBackdrop')) closeModal(); });
  document.addEventListener('keydown', (event) => { if (event.key === 'Escape') closeModal(); });

  function showEnding() {
    const average = Math.round((game.bond + game.patience + game.joy) / 3);
    let heading, reflection;
    if (average >= 72) {
      heading = 'You grew closer, together.';
      reflection = `This week, ${game.name}, you made space for kindness, curiosity, and joy. Your siblings know you are there for them—and you learned that being a good big sibling isn’t about getting everything right. It’s about showing up, listening, and learning side by side.`;
    } else if (game.energy < 24) {
      heading = 'You learned to make room for you, too.';
      reflection = `You cared a lot this week, ${game.name}. And maybe you noticed that being the oldest doesn’t mean doing everything alone. Rest, asking a grown-up for help, and saying what you need are part of caring for your family, too.`;
    } else {
      heading = 'Every little moment helped you grow.';
      reflection = `There were some tricky moments, ${game.name}, and some good ones. You kept trying to understand your siblings and yourself. Being a big sibling is something you practice—not something you have to be perfect at.`;
    }
    openModal(`<div class="eyebrow">Five days, a hundred little moments</div><h2>${heading}</h2><p>${reflection}</p><div class="ending-stats"><div class="ending-stat"><strong>${game.bond}%</strong><small>Family bond</small></div><div class="ending-stat"><strong>${game.patience}%</strong><small>Patience</small></div><div class="ending-stat"><strong>${game.energy}%</strong><small>Your energy</small></div></div><p style="font-size:11px">Your journal has all five moments from your story. Different choices make a different kind of week.</p><div class="start-row"><button class="primary" id="playAgain">Start a new story ↻</button><button class="quiet-btn" data-close>Keep my journal</button></div>`);
    $('#playAgain').addEventListener('click', () => { closeModal(); game = null; $('#gameScreen').classList.remove('active'); $('#setupScreen').classList.add('active'); window.scrollTo({top:0,behavior:'smooth'}); });
  }

  $('#familyButton').addEventListener('click', () => {
    if (!game) return;
    const household = game.household.length ? game.household.join(', ') : 'No grown-ups selected';
    const siblingRows = game.siblings.map((s,i) => `<div class="sibling-mini"><div class="mini-face">${sceneFace(s,i)}</div><div class="mini-info"><strong>${escapeHtml(s.name)}</strong><small>${s.age} years old · ${escapeHtml(s.gender)}</small></div></div>`).join('');
    openModal(`<div class="eyebrow">Your story so far</div><h2>${escapeHtml(game.name)}’s family</h2><p>You’re ${game.age}, living in ${locations[game.home]} with ${escapeHtml(household)}. Your family is your own—and there’s no one right way for it to look.</p><div class="siblings-list">${siblingRows}</div><div class="start-row"><button class="primary" data-close>Back to the story</button></div>`);
  });
  $('#restartButton').addEventListener('click', () => {
    openModal(`<div class="eyebrow">A fresh start</div><h2>Start a new story?</h2><p>Your current journal will be replaced. You can change your family setup before starting again.</p><div class="start-row"><button class="primary" id="confirmRestart">Choose my family</button><button class="quiet-btn" data-close>Stay here</button></div>`);
    $('#confirmRestart').addEventListener('click', () => { closeModal(); game = null; $('#gameScreen').classList.remove('active'); $('#setupScreen').classList.add('active'); window.scrollTo({top:0,behavior:'smooth'}); });
  });

  let toastTimer;
  function showToast(message) {
    const toast = $('#toast'); toast.textContent = message; toast.classList.add('show');
    clearTimeout(toastTimer); toastTimer = setTimeout(() => toast.classList.remove('show'), 2200);
  }
</script>

