const skinOptions = [['🏽','Medium'],['🏻','Light'],['🏼','Warm'],['🏾','Deep'],['🏿','Dark']];
const shirtOptions = [['#e6ad89','Peach'],['#91aaa0','Sage'],['#d7aa62','Gold'],['#8799b5','Blue'],['#b69aaf','Lavender'],['#d58c91','Rose']];
const hairOptions = [['curly','Curly'],['wavy','Wavy'],['braids','Braids'],['pigtails','Pigtails'],['short','Short']];
function appearancePreview(person, key='player') {
  const skin = person.skin || '🏽';
  const faceBase = key === 'adult' ? '🧑' : person.gender === 'Boy' ? '👦' : person.gender === 'Girl' ? '👧' : '🧒';
  const face = faceBase + skin;
  return `<div class="appearance-preview" style="background:${person.shirt || '#e6ad89'}">${face}</div>`;
}
function drawCharacterMaker() {
  const grid = $('#makerGrid');
  const people = [{key:'player', name:($('#playerName').value.trim() || 'You'), gender:$('#playerGender').value, appearance:playerAppearance, role:'Player'}, ...configuredSiblings.map((s,i)=>({key:`sibling-${i}`, name:s.name || `Sibling ${i+1}`, gender:s.gender, appearance:s, role:`Sibling ${i+1}`}))];
  const selectedAdults = [...document.querySelectorAll('input[name="household"]:checked')].map((x)=>x.value);
  selectedAdults.forEach((name) => { if (!adultAppearances[name]) adultAppearances[name] = {skin:'🏽', shirt:'#8799b5', hair:'wavy', gender:'Prefer not to say'}; people.push({key:`adult-${name}`, name, gender:'Adult', appearance:adultAppearances[name], role:'Grown-up'}); });
  grid.innerHTML = people.map((p)=>{
    const a=p.appearance;
    const skinSelect = skinOptions.map(([v,n])=>`<option value="${v}" ${a.skin===v?'selected':''}>${n}</option>`).join('');
    const shirtSelect = shirtOptions.map(([v,n])=>`<option value="${v}" ${a.shirt===v?'selected':''}>${n}</option>`).join('');
    const hairSelect = hairOptions.map(([v,n])=>`<option value="${v}" ${a.hair===v?'selected':''}>${n}</option>`).join('');
    return `<div class="maker-person" data-maker="${p.key}">${appearancePreview({...a,...p},p.key)}<strong>${escapeHtml(p.name)}</strong><label>Skin <select data-maker-key="skin">${skinSelect}</select></label><label>Shirt <select data-maker-key="shirt">${shirtSelect}</select></label><label>Hair <select data-maker-key="hair">${hairSelect}</select></label></div>`;
  }).join('');
  grid.querySelectorAll('.maker-person').forEach((card)=>{
    card.querySelectorAll('select').forEach((select)=>select.addEventListener('change',()=>{
      const key=card.dataset.maker; const field=select.dataset.makerKey;
      if(key==='player') playerAppearance[field]=select.value;
      else if(key.startsWith('sibling-')) configuredSiblings[Number(key.split('-')[1])][field]=select.value;
      else adultAppearances[key.slice(6)][field]=select.value;
      drawCharacterMaker();
    }));
  });
}

