input.newString:
function sceneFace(person, index=0) {
  if (person.appearance && person.appearance.skin) person.skin = person.appearance.skin;
  const pool = faces[person.gender] || faces.Nonbinary;
  return person.age <= 2 ? ['👶🏻','👶🏽','👶🏾'][index % 3] : pool[index % pool.length].replace(/[🏻🏼🏽🏾🏿]/g, person.skin || '🏽');
}

function renderSceneCharacters() {
  if (!game) return;
  const scene=$('.story-scene');
  scene.querySelectorAll('.scene-character').forEach((el)=>el.remove());
  const models=[
    {id:'player',name:game.name,person:{gender:game.gender,age:game.age,...game.playerAppearance},role:'player'},
    ...game.siblings.map((s,i)=>({id:`sibling-${i}`,name:s.name,person:s,role:i===0?'':'sibling'})),
    ...game.adults.map((a,i)=>({id:`adult-${i}`,name:a.name,person:a,role:'adult'}))
  ];
  const slots=[18,32,46,60,74,86];
  models.forEach((m,i)=>{
    const pos=game.positions[m.id] || {left:slots[i % slots.length],bottom:m.role==='player'?58:55};
    const el=document.createElement('div'); el.className=`scene-character ${m.role==='player'?'player':m.role==='adult'?'adult':''}`; el.dataset.character=m.id;
    el.style.left=`${pos.left}%`; el.style.bottom=`${pos.bottom}px`; el.style.setProperty('--shirt',m.person.shirt || (m.role==='adult'?'#8799b5':'#e6ad89'));
    el.innerHTML=`<div class="character-face">${sceneFace(m.person,i)}</div>${m.role==='adult'?'<span class="adult-badge">★</span>':''}<span class="character-name">${escapeHtml(m.name)}</span>`;
    scene.appendChild(el); enableCharacterDrag(el);
  });
}

function enableCharacterDrag(el) {
  let dragging=false;
  const move=(event)=>{
    if(!dragging)return;
    const scene=$('.story-scene'); const rect=scene.getBoundingBufferClientRect ? scene.getBoundingBufferClientRect() : scene.getBoundingClientRect();
    const point=event.touches?event.touches[0]:event;
    const left=Math.max(5,Math.min(95,(point.clientX-rect.left)/rect.width*100));
    const bottom=Math.max(40,Math.min(rect.height-82,rect.bottom-point.clientY));
    el.style.left=`${left}%`; el.style.bottom=`${bottom}px`;
  };
  el.addEventListener('pointerdown',(event)=>{dragging=true;el.setPointerCapture(event.pointerId);event.preventDefault();});
  el.addEventListener('pointermove',(event)=>{if(dragging){const scene=$('.story-scene'),rect=scene.getBoundingClientRect(),point=event;const left=Math.max(5,Math.min(95,(point.clientX-rect.left)/rect.width*100));const bottom=Math.max(40,Math.min(rect.height-82,rect.bottom-point.clientY));el.style.left=`${left}%`;el.style.bottom=`${bottom}px`;}});
  el.addEventListener('pointerup',(event)=>{dragging=false;try{el.releasePointerCapture(event.pointerId);}catch(e){}game.positions[el.dataset.character]={left:parseFloat(el.style.left),bottom:parseFloat(el.style.bottom)};showToast('You moved a family member');});
}

